    "hypotheses": [
      {
        "hypothesis_id": "sqrt_length_law",
        "statement": "Period is proportional to the square root of length: T = 2π sqrt(L/9.81) s, independent of bob mass and release angle.",
        "confidence": 0.55
      },
      {
        "hypothesis_id": "linear_length_law",
        "statement": "Period is proportional to length: T = 2.006*L s, independent of bob mass and release angle.",
        "confidence": 0.25
      },
      {
        "hypothesis_id": "constant_period",
        "statement": "Period is constant at 2.00 s for all allowed controls.",
        "confidence": 0.20
      }
    ]
  },
  "experiment": {
    "intent": "Measure period at a short length to distinguish square-root, linear, and constant length dependence.",
    "apparatus": "simple_pendulum",
    "controls": {
      "length_m": 0.5,
      "bob_mass_kg": 0.1,
      "release_angle_deg": 5
    },
    "readouts": ["period_s"],
    "replicates": 5,
    "forecasts": {
      "period_s": {
        "sqrt_length_law": 1.419,
        "linear_length_law": 1.003,
        "constant_period": 2.00
      }
    }
  },
  "final": null
}

